import { useParams, Link } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { Target, Users, Wallet, Calendar, ListTodo, ArrowRight } from 'lucide-react'
import { projectsService } from '@/integrations/supabase/projects'
import { objectivesService } from '@/integrations/supabase/objectives'

export function ProjectOverviewPage() {
  const { projectId } = useParams()
  const { data: project, isLoading } = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => projectsService.getProject(projectId ?? ''),
    enabled: !!projectId,
  })
  const { data: objectives = [] } = useQuery({
    queryKey: ['objectives', projectId],
    queryFn: () => objectivesService.listObjectives(projectId ?? ''),
    enabled: !!projectId,
  })

  if (isLoading) return <div className="p-6 text-sm text-muted-foreground">Loading…</div>
  if (!project) return <div className="p-6 text-sm text-muted-foreground">Project not found.</div>

  const stats = [
    { label: 'Objectives', value: project.objectivesCount ?? objectives.length, icon: <Target size={14} /> },
    { label: 'Members', value: project.membersCount ?? 0, icon: <Users size={14} /> },
    { label: 'Fund balance', value: `${(project.fundBalance ?? 0).toLocaleString()} XCR`, icon: <Wallet size={14} /> },
    { label: 'Timeline', value: project.endDate ? new Date(project.endDate).toLocaleDateString() : '—', icon: <Calendar size={14} /> },
  ]

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <div className="mb-6">
          <span className="text-xs uppercase tracking-wide text-muted-foreground">{project.status}</span>
          <h2 className="font-semibold text-lg mt-1">{project.title}</h2>
          {project.description && <p className="text-sm text-muted-foreground mt-1">{project.description}</p>}
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          {stats.map((s) => (
            <div key={s.label} className="bg-surface rounded-xl border border-border p-4">
              <div className="flex items-center gap-1.5 text-muted-foreground text-xs">{s.icon} {s.label}</div>
              <p className="text-lg font-semibold mt-1.5">{s.value}</p>
            </div>
          ))}
        </div>
        <div className="bg-surface rounded-xl border border-border">
          <div className="flex items-center justify-between px-5 py-3 border-b border-border">
            <h3 className="font-medium text-sm flex items-center gap-2"><ListTodo size={14} /> Recent objectives</h3>
            <Link to={`/app/project/${project.id}/organiser`} className="text-xs text-accent hover:underline flex items-center gap-1">View all <ArrowRight size={12} /></Link>
          </div>
          <div className="divide-y divide-border">
            {objectives.slice(0, 5).map((o) => (
              <Link key={o.id} to={`/app/objective/${o.id}`} className="flex items-center gap-3 px-5 py-3 hover:bg-muted/40 transition-colors">
                <span className="w-2 h-2 rounded-full bg-accent" />
                <span className="text-sm flex-1">{o.title}</span>
                <span className="text-xs text-muted-foreground capitalize">{o.status.replace('_', ' ')}</span>
              </Link>
            ))}
            {objectives.length === 0 && <p className="px-5 py-8 text-center text-sm text-muted-foreground">No objectives yet.</p>}
          </div>
        </div>
      </div>
    </div>
  )
}
